using OcctSharp.CopiedCollections;
using OcctSharp.CurveSampling;
using OcctSharp.Tests.Shared;
using OcctSharp.Values;
namespace OcctSharp.Runtime.Tests;
public sealed class CurveSamplingTests {
 [Fact]public void SamplingModelingAndIndependentBoundedProjection()=>BatchBBSamplingWorkflow.Run();
 [Fact]public void UniformStraightLineHasEqualArcIntervalsAndIndependentResults(){using var curve=BatchAWGeometryWorkflow.Section(0);var result=CurveComputations.Uniform(curve,.2,.8,7);Assert.True(result.IsDone);Assert.Equal(1.8,result.Length,6);Assert.Equal(.3,result.Step,6);curve.Dispose();Assert.Equal(7,result.Points.Count);for(int i=0;i<7;++i){Assert.Equal(.2+.1*i,result.Parameters[i],6);Assert.Equal(.6+.3*i,result.Points[i].X,6);}}
 [Fact]public void CopiedArcLengthAndSignedAbscissaRespectRequestedInterval(){using var curve=BatchAWGeometryWorkflow.Section(0);var length=CurveComputations.Length(curve,0,1);Assert.True(length.IsDone);Assert.Equal(3,length.Length,6);Assert.Empty(length.Points);var positive=CurveComputations.Abscissa(curve,0,1,.5,.3);var negative=CurveComputations.Abscissa(curve,0,1,.5,-.3);Assert.True(positive.IsDone);Assert.True(negative.IsDone);Assert.Equal(.6,positive.Parameters[0],6);Assert.Equal(.4,negative.Parameters[0],6);var outside=CurveComputations.Abscissa(curve,0,1,.9,1);Assert.False(outside.IsDone);Assert.Empty(outside.Points);}
 [Theory][InlineData(false)][InlineData(true)]public void DeflectionSamplesHaveSdkParametersAndActualMidpointChordQuality(bool tangential){using var curve=BatchBBSamplingWorkflow.Arc();var result=CurveComputations.Deflection(curve,0,1,.01,tangential?.1:null);Assert.True(result.IsDone);Assert.InRange(result.Points.Count,3,4096);for(int i=1;i<result.Points.Count;++i){double u=(result.Parameters[i-1]+result.Parameters[i])*.5;var p=curve.EvalD0(u);var a=result.Points[i-1];var b=result.Points[i];double dx=p.X-(a.X+b.X)*.5,dy=p.Y-(a.Y+b.Y)*.5;Assert.InRange(Math.Sqrt(dx*dx+dy*dy),0,.011);}}
 [Fact]public void PeriodicSeamKeepsUnwrappedFiniteParameters(){using var circle=new GeomCircle(BatchYGeometryWorkflow.Frame,2);double first=5.5,last=7;var result=CurveComputations.Uniform(circle,first,last,9);Assert.True(result.IsDone);Assert.Equal(3,result.Length,6);Assert.Equal(first,result.Parameters[0],6);Assert.Equal(last,result.Parameters[^1],6);for(int i=0;i<result.Points.Count;++i){Assert.Equal(3+2*Math.Cos(result.Parameters[i]),result.Points[i].X,6);Assert.Equal(-2+2*Math.Sin(result.Parameters[i]),result.Points[i].Y,6);}Assert.ThrowsAny<Exception>(()=>CurveComputations.Uniform(circle,0,7,9));}
 [Fact]public void TwoDimensionalCurveSamplesRemainCopiedWithZeroZ(){using var curve=Geom2dBSplineCurveCollections.Create(new(new Point2d[]{new(0,0),new(3,0)}),new([0.0,1]),new([2,2]),1,false);var result=CurveComputations.Uniform(curve,0,1,4);Assert.True(result.IsDone);Assert.Equal(3,result.Length,6);Assert.All(result.Points,p=>Assert.Equal(0,p.Z));var q=CurveComputations.Deflection(curve,0,1,.01);Assert.True(q.IsDone);Assert.Equal(2,q.Points.Count);curve.Dispose();Assert.Equal(3,result.Points[^1].X,6);}
 [Fact]public void OrthogonalCurveProjectionDoesNotGuessEndpointsOutsideItsInterval(){using var curve=BatchAWGeometryWorkflow.Section(0);var result=CurveComputations.Project(curve,new(1.5,2,0),0,1);Assert.True(result.IsDone);Assert.Equal(2,result.MinimumDistance,6);int index=result.UniqueNearestIndex()!.Value;Assert.Equal(.5,result.Candidates[index].U,6);curve.Dispose();Assert.Equal(1.5,result.Candidates[index].Point.X,6);using var second=BatchAWGeometryWorkflow.Section(0);var absent=CurveComputations.Project(second,new(2.5,1,0),0,.2);Assert.False(absent.IsDone);Assert.Empty(absent.Candidates);}
 [Fact]public void SurfaceProjectionCopiesExplicitRectangleAndParameters(){using var surface=BatchBBSamplingWorkflow.Plane();var result=CurveComputations.Project(surface,new(2,1.5,2),.2,.8,.2,.8);Assert.True(result.IsDone);int index=result.UniqueNearestIndex()!.Value;Assert.Equal(.5,result.Candidates[index].U,6);Assert.Equal(.5,result.Candidates[index].V,6);Assert.Equal(0,result.Candidates[index].Point.Z,6);surface.Dispose();Assert.Equal(2,result.MinimumDistance,6);using var other=BatchBBSamplingWorkflow.Plane();Assert.ThrowsAny<Exception>(()=>CurveComputations.Project(other,new(2,1.5,2),-1,.8,.2,.8));}
 [Fact]public void InvalidTolerancesCountsAndDomainsDoNotRunUnboundedAlgorithms(){using var curve=BatchBBSamplingWorkflow.Arc();Assert.ThrowsAny<Exception>(()=>CurveComputations.Uniform(curve,0,1,4097));Assert.ThrowsAny<Exception>(()=>CurveComputations.Uniform(curve,0,1,1));Assert.ThrowsAny<Exception>(()=>CurveComputations.Deflection(curve,0,1,0));Assert.ThrowsAny<Exception>(()=>CurveComputations.Deflection(curve,0,1,.01,0));Assert.ThrowsAny<Exception>(()=>CurveComputations.Uniform(curve,-1,1,10));Assert.ThrowsAny<Exception>(()=>CurveComputations.Length(curve,0,1,double.NaN));}
 [Fact]public void DegenerateCurveReturnsNoUninitializedSamples(){using var curve=GeomBSplineCurveCollections.Create(new(new Coordinates3d[]{new(0,0,0),new(0,0,0)}),new([0.0,1]),new([2,2]),1,false);var samples=CurveComputations.Uniform(curve,0,1,5);Assert.False(samples.IsDone);Assert.Empty(samples.Points);Assert.Empty(samples.Parameters);Assert.Equal(0,samples.Length);}
 [Fact]public void EqualProjectionCandidatesStayAmbiguous(){var candidates=new ProjectionCandidate[]{new(new(0,0,0),0,0,1),new(new(2,0,0),1,0,1)};var result=new BoundedProjectionResult(CurveComputationStatus.Complete,Array.AsReadOnly(candidates),1);Assert.Null(result.UniqueNearestIndex());Assert.Throws<ArgumentOutOfRangeException>(()=>result.UniqueNearestIndex(double.NaN));}
 [Fact]public void ConcurrentPrivateSamplingDoesNotShareBuffers(){Parallel.For(0,8,_=>{using var curve=BatchAWGeometryWorkflow.Section(0);var result=CurveComputations.Uniform(curve,0,1,9);Assert.True(result.IsDone);Assert.Equal(9,result.Points.Count);Assert.Equal(3,result.Length,6);});}
 [Fact]public void NativeEvaluationBudgetReturnsNoPartialDistribution(){using var curve=BatchBBSamplingWorkflow.Arc();var result=CurveComputations.Deflection(curve,0,1,1e-12);Assert.Equal(CurveComputationStatus.BudgetExceeded,result.Status);Assert.Empty(result.Points);Assert.Empty(result.Parameters);}
 [Fact]public void TwoDimensionalSignedAbscissaUsesTheSameFiniteDomain(){using var curve=Geom2dBSplineCurveCollections.Create(new(new Point2d[]{new(0,0),new(3,0)}),new([0.0,1]),new([2,2]),1,false);var result=CurveComputations.Abscissa(curve,0,1,.5,-.3);Assert.True(result.IsDone);Assert.Equal(.4,result.Parameters.Single(),6);Assert.Equal(1.2,result.Points.Single().X,6);Assert.Equal(0,result.Points.Single().Z);}
}
